// Self-checking testbench for axi4_lite_regs.
// Inputs are driven just after the falling edge; handshakes are sampled at
// the falling edge, before the rising edge that completes them.
`timescale 1ns/1ps

module axi4_lite_regs_tb;

  localparam [1:0] RESP_OKAY   = 2'b00;
  localparam [1:0] RESP_SLVERR = 2'b10;

  reg         clk = 1'b0;
  reg         aresetn;
  reg  [3:0]  awaddr;
  reg         awvalid;
  wire        awready;
  reg  [31:0] wdata;
  reg  [3:0]  wstrb;
  reg         wvalid;
  wire        wready;
  wire [1:0]  bresp;
  wire        bvalid;
  reg         bready;
  reg  [3:0]  araddr;
  reg         arvalid;
  wire        arready;
  wire [31:0] rdata;
  wire [1:0]  rresp;
  wire        rvalid;
  reg         rready;

  axi4_lite_regs dut (
    .aclk           (clk),
    .aresetn        (aresetn),
    .s_axil_awaddr  (awaddr),
    .s_axil_awvalid (awvalid),
    .s_axil_awready (awready),
    .s_axil_wdata   (wdata),
    .s_axil_wstrb   (wstrb),
    .s_axil_wvalid  (wvalid),
    .s_axil_wready  (wready),
    .s_axil_bresp   (bresp),
    .s_axil_bvalid  (bvalid),
    .s_axil_bready  (bready),
    .s_axil_araddr  (araddr),
    .s_axil_arvalid (arvalid),
    .s_axil_arready (arready),
    .s_axil_rdata   (rdata),
    .s_axil_rresp   (rresp),
    .s_axil_rvalid  (rvalid),
    .s_axil_rready  (rready)
  );

  always #5 clk = ~clk;

  // Expected-value model
  reg [31:0] model [0:3];

  integer passed;
  integer failed;
  integer test_no;
  integer ok;
  reg [8*64-1:0] nonce;

  // ------------------------------------------------------------------
  // Helpers
  // ------------------------------------------------------------------
  function [31:0] merge32;
    input [31:0] o;
    input [31:0] d;
    input [3:0]  s;
    begin
      merge32[7:0]   = s[0] ? d[7:0]   : o[7:0];
      merge32[15:8]  = s[1] ? d[15:8]  : o[15:8];
      merge32[23:16] = s[2] ? d[23:16] : o[23:16];
      merge32[31:24] = s[3] ? d[31:24] : o[31:24];
    end
  endfunction

  function is_mapped_tb;
    input [3:0] a;
    begin
      is_mapped_tb = (a[1:0] == 2'b00);
    end
  endfunction

  task check;
    input         cond;
    input integer id;
    begin
      if (cond) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("FAIL test %0d check %0d at time %0t", test_no, id, $time);
      end
    end
  endtask

  task check_eq32;
    input [31:0]  got;
    input [31:0]  exp;
    input integer id;
    begin
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("FAIL test %0d check %0d at time %0t: got 0x%08h expected 0x%08h",
               test_no, id, $time, got, exp);
      end
    end
  endtask

  task check_eq2;
    input [1:0]   got;
    input [1:0]   exp;
    input integer id;
    begin
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("FAIL test %0d check %0d at time %0t: got %b expected %b",
               test_no, id, $time, got, exp);
      end
    end
  endtask

  // Called at the falling edge right after the edge that completed the write.
  task b_phase;
    input [1:0]   exp_resp;
    input integer stall;
    integer lat;
    integer k;
    begin
      lat = 1;
      while (!bvalid && lat < 8) begin
        @(negedge clk);
        lat = lat + 1;
      end
      check(bvalid === 1'b1, 100);
      check(lat <= 2, 101);
      check_eq2(bresp, exp_resp, 102);
      for (k = 0; k < stall; k = k + 1) begin
        check(awready === 1'b0 && wready === 1'b0, 103);
        @(negedge clk);
        check(bvalid === 1'b1, 104);
        check_eq2(bresp, exp_resp, 105);
      end
      check(awready === 1'b0 && wready === 1'b0, 103);
      bready = 1'b1;
      @(negedge clk);
      bready = 1'b0;
      check(bvalid === 1'b0, 106);
      check(awready === 1'b1 && wready === 1'b1, 107);
    end
  endtask

  // Called at the falling edge right after the edge that accepted AR.
  task r_phase;
    input [31:0]  exp_data;
    input [1:0]   exp_resp;
    input integer stall;
    integer lat;
    integer k;
    begin
      lat = 1;
      while (!rvalid && lat < 8) begin
        @(negedge clk);
        lat = lat + 1;
      end
      check(rvalid === 1'b1, 130);
      check(lat <= 2, 131);
      check_eq32(rdata, exp_data, 132);
      check_eq2(rresp, exp_resp, 133);
      for (k = 0; k < stall; k = k + 1) begin
        check(arready === 1'b0, 134);
        @(negedge clk);
        check(rvalid === 1'b1, 135);
        check_eq32(rdata, exp_data, 136);
        check_eq2(rresp, exp_resp, 137);
      end
      check(arready === 1'b0, 134);
      rready = 1'b1;
      @(negedge clk);
      rready = 1'b0;
      check(rvalid === 1'b0, 138);
      check(arready === 1'b1, 139);
    end
  endtask

  // order: 0 = AW and W together, 1 = AW first, 2 = W first.
  // gap: cycles (counted from the start) before the later channel is raised.
  task do_write;
    input [3:0]   addr;
    input [31:0]  data;
    input [3:0]   strb;
    input integer order;
    input integer gap;
    input integer stall;
    reg           aw_done;
    reg           w_done;
    reg           aw_fire;
    reg           w_fire;
    reg [1:0]     exp_resp;
    integer       iter;
    begin
      exp_resp = is_mapped_tb(addr) ? RESP_OKAY : RESP_SLVERR;
      check(bvalid === 1'b0, 110);
      aw_done = 1'b0;
      w_done  = 1'b0;
      iter    = 0;
      if (order != 2) begin
        awaddr  = addr;
        awvalid = 1'b1;
      end
      if (order != 1) begin
        wdata  = data;
        wstrb  = strb;
        wvalid = 1'b1;
      end
      while (!(aw_done && w_done) && iter < 32) begin
        check(bvalid === 1'b0, 111);
        if (aw_done && !w_done) check(awready === 1'b0, 113);
        if (w_done && !aw_done) check(wready === 1'b0, 114);
        aw_fire = awvalid && awready;
        w_fire  = wvalid && wready;
        @(negedge clk);
        iter = iter + 1;
        if (aw_fire) begin
          aw_done = 1'b1;
          awvalid = 1'b0;
        end
        if (w_fire) begin
          w_done = 1'b1;
          wvalid = 1'b0;
        end
        if (!aw_done && !awvalid && iter >= gap) begin
          awaddr  = addr;
          awvalid = 1'b1;
        end
        if (!w_done && !wvalid && iter >= gap) begin
          wdata  = data;
          wstrb  = strb;
          wvalid = 1'b1;
        end
      end
      check(aw_done && w_done, 112);
      if (order == 0) check(iter == 1, 115);
      if (exp_resp == RESP_OKAY) begin
        model[addr[3:2]] = merge32(model[addr[3:2]], data, strb);
      end
      b_phase(exp_resp, stall);
    end
  endtask

  task do_read;
    input [3:0]   addr;
    input integer stall;
    reg [31:0]    exp_data;
    reg [1:0]     exp_resp;
    reg           fired;
    integer       iter;
    begin
      if (is_mapped_tb(addr)) begin
        exp_data = model[addr[3:2]];
        exp_resp = RESP_OKAY;
      end else begin
        exp_data = 32'h0000_0000;
        exp_resp = RESP_SLVERR;
      end
      check(rvalid === 1'b0, 120);
      araddr  = addr;
      arvalid = 1'b1;
      fired   = 1'b0;
      iter    = 0;
      while (!fired && iter < 32) begin
        check(rvalid === 1'b0, 121);
        fired = arvalid && arready;
        @(negedge clk);
        iter = iter + 1;
      end
      arvalid = 1'b0;
      check(fired, 122);
      check(iter == 1, 123);
      r_phase(exp_data, exp_resp, stall);
    end
  endtask

  task read_all;
    begin
      do_read(4'h0, 0);
      do_read(4'h4, 0);
      do_read(4'h8, 0);
      do_read(4'hC, 0);
    end
  endtask

  task model_reset;
    begin
      model[0] = 32'h0000_0000;
      model[1] = 32'h0000_0000;
      model[2] = 32'h0000_0000;
      model[3] = 32'h0000_0000;
    end
  endtask

  // ------------------------------------------------------------------
  // Test sequence
  // ------------------------------------------------------------------
  initial begin
    passed  = 0;
    failed  = 0;
    test_no = 0;
    nonce   = {(8*64){1'b0}};
    aresetn = 1'b0;
    awaddr  = 4'h0;
    awvalid = 1'b0;
    wdata   = 32'h0000_0000;
    wstrb   = 4'h0;
    wvalid  = 1'b0;
    bready  = 1'b0;
    araddr  = 4'h0;
    arvalid = 1'b0;
    rready  = 1'b0;
    model_reset;

    // ---- Test 1: reset values -------------------------------------
    test_no = 1;
    repeat (3) @(negedge clk);
    check(bvalid === 1'b0 && rvalid === 1'b0, 1);
    aresetn = 1'b1;
    @(negedge clk);
    check(awready === 1'b1 && wready === 1'b1 && arready === 1'b1, 2);
    check(bvalid === 1'b0 && rvalid === 1'b0, 3);
    check_eq2(bresp, RESP_OKAY, 4);
    check_eq2(rresp, RESP_OKAY, 5);
    check_eq32(rdata, 32'h0000_0000, 6);
    read_all;

    // ---- Test 2: write then read every register --------------------
    test_no = 2;
    do_write(4'h0, 32'hDEAD_BEEF, 4'hF, 0, 0, 0);
    do_write(4'h4, 32'h1234_5678, 4'hF, 0, 0, 0);
    do_write(4'h8, 32'hA5A5_5A5A, 4'hF, 0, 0, 0);
    do_write(4'hC, 32'h0F0F_F0F0, 4'hF, 0, 0, 0);
    read_all;

    // ---- Test 3: byte strobes ---------------------------------------
    test_no = 3;
    do_write(4'h8, 32'h1122_3344, 4'b0101, 0, 0, 0);
    do_read(4'h8, 0);
    do_write(4'h8, 32'h9988_7766, 4'b1010, 0, 0, 0);
    do_read(4'h8, 0);
    do_write(4'h8, 32'hFFFF_FFFF, 4'b0000, 0, 0, 0);
    do_read(4'h8, 0);
    do_write(4'h4, 32'hCC00_0000, 4'b1000, 0, 0, 0);
    do_read(4'h4, 0);
    do_write(4'hC, 32'h0000_00EE, 4'b0001, 0, 0, 0);
    do_read(4'hC, 0);

    // ---- Test 4: AW/W ordering ---------------------------------------
    test_no = 4;
    do_write(4'h0, 32'hA0A0_A0A0, 4'hF, 1, 1, 0);
    do_write(4'h4, 32'hB1B1_B1B1, 4'hF, 1, 3, 0);
    do_write(4'h8, 32'hC2C2_C2C2, 4'hF, 2, 1, 0);
    do_write(4'hC, 32'hD3D3_D3D3, 4'hF, 2, 4, 0);
    do_write(4'h0, 32'h0000_00FF, 4'b0001, 2, 2, 1);
    do_write(4'h4, 32'h00FF_0000, 4'b0100, 1, 2, 1);
    read_all;

    // ---- Test 5: B and R back-pressure ---------------------------------
    test_no = 5;
    do_write(4'h8, 32'hFEED_FACE, 4'hF, 0, 0, 5);
    do_read(4'h8, 6);
    do_write(4'h0, 32'h1357_9BDF, 4'hF, 1, 2, 3);
    do_read(4'h0, 3);
    do_write(4'hC, 32'h2468_ACE0, 4'hF, 2, 2, 4);
    do_read(4'hC, 1);

    // ---- Test 6: back-to-back transactions ----------------------------
    test_no = 6;
    do_write(4'h0, 32'h0101_0101, 4'hF, 0, 0, 0);
    do_write(4'h4, 32'h0202_0202, 4'hF, 0, 0, 0);
    do_write(4'h8, 32'h0303_0303, 4'hF, 0, 0, 0);
    do_write(4'hC, 32'h0404_0404, 4'hF, 0, 0, 0);
    do_read(4'h0, 0);
    do_read(4'h4, 0);
    do_read(4'h8, 0);
    do_read(4'hC, 0);
    do_read(4'h0, 0);

    // ---- Test 7: SLVERR policy -----------------------------------------
    test_no = 7;
    do_write(4'h5, 32'hFFFF_FFFF, 4'hF, 0, 0, 0);
    do_write(4'hE, 32'hEEEE_EEEE, 4'hF, 1, 1, 2);
    do_write(4'h3, 32'h3333_3333, 4'hF, 2, 1, 0);
    do_write(4'h1, 32'h1111_1111, 4'b0000, 0, 0, 0);
    read_all;
    do_read(4'h5, 0);
    do_read(4'hE, 2);
    do_read(4'h1, 0);
    do_read(4'h7, 1);
    do_write(4'h4, 32'h5A5A_A5A5, 4'hF, 0, 0, 0);
    do_read(4'h4, 0);

    // ---- Test 8: requests held while the response is stalled -----------
    test_no = 8;
    awaddr  = 4'h0;
    awvalid = 1'b1;
    wdata   = 32'hCAFE_F00D;
    wstrb   = 4'hF;
    wvalid  = 1'b1;
    check(awready === 1'b1 && wready === 1'b1, 800);
    @(negedge clk);
    model[0] = 32'hCAFE_F00D;
    check(bvalid === 1'b1, 801);
    check_eq2(bresp, RESP_OKAY, 802);
    // next write presented while B is stalled
    awaddr  = 4'h4;
    awvalid = 1'b1;
    wdata   = 32'h0BAD_C0DE;
    wstrb   = 4'hF;
    wvalid  = 1'b1;
    repeat (3) begin
      check(awready === 1'b0 && wready === 1'b0, 803);
      @(negedge clk);
      check(bvalid === 1'b1, 804);
      check_eq2(bresp, RESP_OKAY, 805);
    end
    check(awready === 1'b0 && wready === 1'b0, 803);
    bready = 1'b1;
    @(negedge clk);
    bready = 1'b0;
    check(bvalid === 1'b0, 806);
    check(awready === 1'b1 && wready === 1'b1, 807);
    @(negedge clk);
    awvalid = 1'b0;
    wvalid  = 1'b0;
    model[1] = 32'h0BAD_C0DE;
    b_phase(RESP_OKAY, 0);
    // next read presented while R is stalled
    araddr  = 4'h0;
    arvalid = 1'b1;
    check(arready === 1'b1, 810);
    @(negedge clk);
    check(rvalid === 1'b1, 811);
    check_eq32(rdata, model[0], 812);
    araddr = 4'h4;
    repeat (3) begin
      check(arready === 1'b0, 813);
      @(negedge clk);
      check(rvalid === 1'b1, 814);
      check_eq32(rdata, model[0], 815);
      check_eq2(rresp, RESP_OKAY, 816);
    end
    rready = 1'b1;
    @(negedge clk);
    rready = 1'b0;
    check(rvalid === 1'b0, 817);
    check(arready === 1'b1, 818);
    @(negedge clk);
    arvalid = 1'b0;
    r_phase(model[1], RESP_OKAY, 0);

    // ---- Test 9: read and write accepted on the same clock --------------
    test_no = 9;
    awaddr  = 4'h8;
    awvalid = 1'b1;
    wdata   = 32'h5555_AAAA;
    wstrb   = 4'hF;
    wvalid  = 1'b1;
    araddr  = 4'h0;
    arvalid = 1'b1;
    check(awready === 1'b1 && wready === 1'b1 && arready === 1'b1, 900);
    @(negedge clk);
    awvalid = 1'b0;
    wvalid  = 1'b0;
    arvalid = 1'b0;
    check(bvalid === 1'b1 && rvalid === 1'b1, 901);
    check_eq2(bresp, RESP_OKAY, 902);
    check_eq32(rdata, model[0], 903);
    check_eq2(rresp, RESP_OKAY, 904);
    model[2] = 32'h5555_AAAA;
    bready = 1'b1;
    rready = 1'b1;
    @(negedge clk);
    bready = 1'b0;
    rready = 1'b0;
    check(bvalid === 1'b0 && rvalid === 1'b0, 905);
    do_read(4'h8, 0);

    // ---- Test 10: reset during traffic (half write, pending R) -----------
    test_no = 10;
    do_write(4'h4, 32'h1111_1111, 4'hF, 0, 0, 0);
    awaddr  = 4'h8;
    awvalid = 1'b1;
    araddr  = 4'h4;
    arvalid = 1'b1;
    @(negedge clk);
    awvalid = 1'b0;
    arvalid = 1'b0;
    check(awready === 1'b0, 1000);
    check(bvalid === 1'b0, 1001);
    check(rvalid === 1'b1, 1002);
    aresetn = 1'b0;
    @(negedge clk);
    check(bvalid === 1'b0 && rvalid === 1'b0, 1003);
    @(negedge clk);
    aresetn = 1'b1;
    model_reset;
    check(awready === 1'b1 && wready === 1'b1 && arready === 1'b1, 1004);
    check(bvalid === 1'b0 && rvalid === 1'b0, 1005);
    // W alone: the AW from before reset was discarded, so no B may appear
    wdata  = 32'h7777_7777;
    wstrb  = 4'hF;
    wvalid = 1'b1;
    @(negedge clk);
    wvalid = 1'b0;
    repeat (3) begin
      check(bvalid === 1'b0, 1006);
      check(wready === 1'b0, 1007);
      @(negedge clk);
    end
    check(bvalid === 1'b0, 1006);
    awaddr  = 4'hC;
    awvalid = 1'b1;
    check(awready === 1'b1, 1008);
    @(negedge clk);
    awvalid = 1'b0;
    model[3] = 32'h7777_7777;
    b_phase(RESP_OKAY, 0);
    read_all;

    // ---- Test 11: reset while B is pending -------------------------------
    test_no = 11;
    awaddr  = 4'h0;
    awvalid = 1'b1;
    wdata   = 32'h8888_8888;
    wstrb   = 4'hF;
    wvalid  = 1'b1;
    @(negedge clk);
    awvalid = 1'b0;
    wvalid  = 1'b0;
    check(bvalid === 1'b1, 1100);
    aresetn = 1'b0;
    @(negedge clk);
    check(bvalid === 1'b0, 1101);
    aresetn = 1'b1;
    model_reset;
    check(awready === 1'b1 && wready === 1'b1 && arready === 1'b1, 1102);
    read_all;

    // ---- Verdict ----------------------------------------------------------
    ok = $value$plusargs("nirmaan_nonce=%s", nonce);
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule
